stats_jelly_bean.css:
// [3] caminho: stats_jelly_bean.css
.widget.Stats {
  background: linear-gradient(145deg, #ffffff, #f0f4f8);
  padding: 2rem 1.5rem; border-radius: 24px;
  border: 1px solid #e0e0e0; text-align: center;
  position: relative; overflow: hidden;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
  margin-bottom: 2rem;
}
.widget.Stats h2.title { display: none !important; }
.widget.Stats::after {
  content: "\F33D";
  font-family: "bootstrap-icons";
  position: absolute; top: -15px; right: -15px;
  font-size: 8rem; color: var(--bulma-primary);
  opacity: 0.04; z-index: 0;
  animation: jellyFloat 6s ease-in-out infinite;
}
.widget.Stats .widget-content {
  position: relative; z-index: 2;
  display: flex; flex-direction: column; align-items: center;
}
.widget.Stats .widget-content::before {
  content: "\F33D";
  font-family: "bootstrap-icons";
  display: flex; align-items: center; justify-content: center;
  width: 65px; height: 65px;
  margin: 0 auto 1.2rem auto;
  background: var(--bulma-primary); color: #ffffff; font-size: 2rem;
  border-radius: 40% 60% 65% 35% / 40% 45% 55% 60%;
  box-shadow: 0 8px 15px rgba(var(--sl-primary),0.3);
  animation: jellySquash 2.5s infinite alternate ease-in-out;
}
.widget.Stats span[dir="ltr"], .widget.Stats .widget-content > span {
  display: block !important; font-size: 3rem !important;
  font-weight: 900 !important; color: var(--bulma-text) !important;
  line-height: 1 !important; letter-spacing: -2px !important;
  animation: countSlideUp 1s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
.widget.Stats span[dir="ltr"]::after, .widget.Stats .widget-content > span::after {
  content: "Visualizacoes Totais";
  display: block; font-size: 0.8rem; font-weight: 700;
  color: #888; text-transform: uppercase; letter-spacing: 1px; margin-top: 8px;
}
.widget.Stats img { display: none !important; }
@keyframes countSlideUp {
  0% { opacity: 0; transform: translateY(40px) scale(0.8); filter: blur(5px); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}
@keyframes jellySquash {
  0% { transform: scale(1) rotate(0deg); border-radius: 40% 60% 65% 35% / 40% 45% 55% 60%; }
  50% { transform: scale(1.05) rotate(8deg); border-radius: 50% 50% 50% 50% / 50% 50% 50% 50%; }
  100% { transform: scale(0.95) rotate(-8deg); border-radius: 60% 40% 35% 65% / 55% 45% 40% 60%; }
}
@keyframes jellyFloat {
  0%, 100% { transform: translateY(0) rotate(15deg); }
  50% { transform: translateY(-20px) rotate(25deg); }
}

