widget_cookie_card_central.javascript:
document.addEventListener('DOMContentLoaded', function() {
  const cookieBanner = document.getElementById('bulmaCookieBanner');
  const acceptBtn = document.getElementById('bulmaCookieAccept');
  const cookieName = 'bulma_mobile_cookies_accepted';
  if (!localStorage.getItem(cookieName)) {
    setTimeout(() => { cookieBanner.classList.add('show'); }, 1000);
  }
  acceptBtn.addEventListener('click', function() {
    localStorage.setItem(cookieName, 'true');
    cookieBanner.classList.remove('show');
    setTimeout(() => { cookieBanner.remove(); }, 500);
  });
});
